-- =====================================================================================
-- FLYWAY MIGRATION V1  (file name format:  V<version>__<description>.sql)
--
-- Flyway runs every script in src/main/resources/db/migration exactly ONCE, in version order,
-- and records what it ran in a table called "flyway_schema_history".
-- RULE: never edit a migration that has already run somewhere - add a new V3__... file instead.
--
-- The SQL is written so it works on both PostgreSQL and H2 (in PostgreSQL compatibility mode).
-- "GENERATED BY DEFAULT AS IDENTITY" = auto-increment id (SQL standard, supported by both).
-- =====================================================================================

CREATE TABLE users (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(100) NOT NULL,
    email       VARCHAR(255) NOT NULL,
    password    VARCHAR(255) NOT NULL,          -- BCrypt hash, never plain text
    role        VARCHAR(20)  NOT NULL,          -- 'USER' or 'ADMIN'
    created_at  TIMESTAMP    NOT NULL,
    updated_at  TIMESTAMP    NOT NULL,
    CONSTRAINT uk_users_email UNIQUE (email)
);

CREATE TABLE projects (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(100)  NOT NULL,
    description VARCHAR(1000),
    owner_id    BIGINT        NOT NULL,
    created_at  TIMESTAMP     NOT NULL,
    updated_at  TIMESTAMP     NOT NULL,
    -- FOREIGN KEY: the database itself guarantees owner_id points to an existing user
    CONSTRAINT fk_projects_owner FOREIGN KEY (owner_id) REFERENCES users (id)
);

CREATE TABLE tasks (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title        VARCHAR(200)  NOT NULL,
    description  VARCHAR(2000),
    status       VARCHAR(20)   NOT NULL,        -- TODO / IN_PROGRESS / COMPLETED
    priority     VARCHAR(20)   NOT NULL,        -- LOW / MEDIUM / HIGH
    due_date     DATE,
    project_id   BIGINT        NOT NULL,
    assignee_id  BIGINT,                        -- nullable: unassigned task
    created_at   TIMESTAMP     NOT NULL,
    updated_at   TIMESTAMP     NOT NULL,
    -- deleting a project deletes its tasks; deleting a user just un-assigns their tasks
    CONSTRAINT fk_tasks_project  FOREIGN KEY (project_id)  REFERENCES projects (id) ON DELETE CASCADE,
    CONSTRAINT fk_tasks_assignee FOREIGN KEY (assignee_id) REFERENCES users (id)    ON DELETE SET NULL
);
